  const [licenseTier, setLicenseTier] = useState<'standard' | 'extended'>('standard');
  const [activeSpecTab, setActiveSpecTab] = useState<'specs' | 'manifest' | 'changelog' | 'curriculum'>('specs');
  const [newRating, setNewRating] = useState(5);
  const [newComment, setNewComment] = useState('');
  const [showReviewForm, setShowReviewForm] = useState(false);

  // Reset tab & tier when navigating between items so activeSpecTab is never invalid
  useEffect(() => {
    setActiveSpecTab('specs');
    setLicenseTier('standard');
  }, [id]);

  const manifestItems = useMemo(
    () => (product ? getNormalizedManifest(product) : []),
    [product]
  );

